export default {
  "j02-n01": {
    "8-9": {
      en: own({ title: "Seen in the Desert", bibleStory: "Genesis 16 & 21", readPassage: "Genesis 16:6–13",
        story: ["Hagar was an Egyptian servant in Abraham and Sarah’s household. Sarah treated her harshly, and Hagar ran away into the desert. She was a foreigner, a servant and a runaway: about as forgotten as a person could feel.", "By a spring of water on the road to Egypt, the angel of the Lord found her. Notice the word ‘found’. Hagar wasn’t looking for God, but God was looking for her. ‘Hagar, slave of Sarai, where have you come from, and where are you going?’ God knew her name and her story.", "God told her that He had heard her misery. He promised that her son, Ishmael, would grow up and have many descendants. Ishmael’s name means ‘God hears’.", "Hagar responded by giving God a name: ‘You are the God who sees me.’ In Hebrew, El Roi. She is the only person in the Bible who gave God a name, and it came from her own experience of being seen.", "Years later, Hagar and Ishmael were sent away and their water ran out. Hagar couldn’t bear to watch her son die, so she sat a distance away and cried. ‘God heard the boy crying,’ and He opened her eyes to see a well. The God who sees is also the God who hears.", "You might sometimes feel invisible: at school, among friends, even at home. But you are never unseen by God. He knows exactly where you are and how you feel."],
        verse: simple("You are the God who sees me.", "Genesis 16:13"),
        lessons: ["God sees and knows each person, especially those who feel forgotten.", "God goes looking for people who run away and feel alone.", "The God who sees is also the God who hears our cries."],
        questions: ["Why do you think Hagar felt so alone?", "What do the names ‘El Roi’ and ‘Ishmael’ tell us about God?", "When do you feel unseen? How could knowing God sees you help?"],
        listen: "Be still for one minute. Ask God: ‘What do you see when you look at me?’ Listen, and write down what you sense. God’s words will always be kind and true.",
        prayer: ["El Roi, you are the God who sees me.", "Right now I feel…", "Thank you that you see me and hear me."],
        mission: { compass: "love", text: "Tomorrow, notice someone who might feel invisible, and do something kind so they know they’re seen." },
        journal: "Write about a time you felt invisible. Then write what El Roi would say to you in that moment." }),
      af: own({ title: "Raakgesien in die Woestyn", bibleStory: "Genesis 16 & 21", readPassage: "Genesis 16:6–13",
        story: ["Hagar was ’n Egiptiese diensmeisie in Abraham en Sara se huishouding. Sara het haar hard behandel, en Hagar het die woestyn in weggehardloop. Sy was ’n vreemdeling, ’n diensmeisie en ’n weghardloper: omtrent so vergete as wat ’n mens kan voel.", "By ’n fontein op die pad na Egipte het die engel van die Here haar gekry. Let op die woord ‘gekry’. Hagar het nie na God gesoek nie, maar God het na haar gesoek. ‘Hagar, slavin van Sarai, waar kom jy vandaan, en waarheen gaan jy?’ God het haar naam en haar storie geken.", "God het vir haar gesê dat Hy van haar ellende gehoor het. Hy het belowe dat haar seun, Ismael, sou grootword en baie nakomelinge sou hê. Ismael se naam beteken ‘God hoor’.", "Hagar het geantwoord deur God ’n naam te gee: ‘U is die God wat my sien.’ In Hebreeus, El Roi. Sy is die enigste mens in die Bybel wat God ’n naam gegee het, en dit het uit haar eie ervaring gekom van om raakgesien te word.", "Jare later is Hagar en Ismael weggestuur en hulle water het opgeraak. Hagar kon nie verdra om haar seun te sien sterf nie, toe gaan sit sy ’n entjie weg en huil. ‘God het die seun hoor huil,’ en Hy het haar oë oopgemaak om ’n put te sien. Die God wat sien, is ook die God wat hoor.", "Jy voel dalk soms onsigbaar: by die skool, tussen maats, selfs by die huis. Maar God sien jou altyd. Hy weet presies waar jy is en hoe jy voel."],
        verse: simple("U is die God wat my sien.", "Genesis 16:13"),
        lessons: ["God sien en ken elke mens, veral die wat vergete voel.", "God gaan soek na mense wat weghardloop en alleen voel.", "Die God wat sien, is ook die God wat ons hoor roep."],
        questions: ["Hoekom dink jy het Hagar so alleen gevoel?", "Wat sê die name ‘El Roi’ en ‘Ismael’ vir ons oor God?", "Wanneer voel jy onsigbaar? Hoe kan dit help om te weet God sien jou?"],
        listen: "Wees een minuut lank stil. Vra God: ‘Wat sien U as U na my kyk?’ Luister, en skryf neer wat jy aanvoel. God se woorde sal altyd liefdevol en waar wees.",
        prayer: ["El Roi, U is die God wat my sien.", "Op die oomblik voel ek…", "Dankie dat U my sien en hoor."],
        mission: { compass: "love", text: "Kyk môre na iemand wat dalk onsigbaar voel, en doen iets gaafs sodat hulle weet hulle word raakgesien." },
        journal: "Skryf oor ’n keer toe jy onsigbaar gevoel het. Skryf dan wat El Roi op daardie oomblik vir jou sou sê." }),
    },
    "10-12": {
      en: own({ title: "The God Who Sees Me", bibleStory: "Genesis 16 & 21", readPassage: "Genesis 16:1–16 and 21:14–20",
        story: ["Genesis 16 is an uncomfortable chapter. Sarah, unable to have children, gives her Egyptian servant Hagar to Abraham so that Hagar can have a child for her. It was a common custom then, but it was not God’s plan, and it goes badly. Hagar becomes pregnant, tension explodes, and Sarah mistreats her until Hagar flees into the desert.", "Think about Hagar’s position: a foreign slave woman, pregnant, alone, with no rights and no protection. She had been used by others and then pushed out. In her world, she was the least important person in the story.", "But read verse 7: ‘The angel of the Lord found Hagar near a spring in the desert.’ The first time an angel appears in the Bible, he comes not to a king or a patriarch, but to a runaway slave. God addresses her by name and asks two questions: ‘Where have you come from, and where are you going?’ God invites her to tell her story.", "He doesn’t remove all her difficulties; He tells her to go back. But He gives her a promise, a future and a son whose name, Ishmael, means ‘God hears’. And Hagar responds with theology from her own experience: ‘You are the God who sees me… I have now seen the One who sees me.’", "In chapter 21, abandoned again with Ishmael, she sits down to cry, and ‘God heard the boy crying’. He opened her eyes to a well that had been there all along.", "What does this teach us? God is not only the God of the important people in the story. He notices the overlooked, the used and the hurting. If you have ever felt used, excluded or invisible, Hagar’s God sees you too. And He calls His followers to see the Hagars around them."],
        verse: simple("You are the God who sees me… I have now seen the One who sees me.", "Genesis 16:13"),
        lessons: ["God sees and cares for the overlooked, the used and the hurting.", "God invites us to bring Him our whole story: where we have come from and where we are going.", "God’s followers are called to see the ‘Hagars’ around them."],
        questions: ["What does it reveal about God that the first angel in the Bible appears to a runaway slave?", "Have you ever felt used, excluded or invisible? What does El Roi say to that?", "Who is a ‘Hagar’ in your world who needs to be seen?"],
        listen: "Set a timer for two minutes. Answer God’s two questions honestly in writing: ‘Where have you come from? Where are you going?’ Then ask Him what He wants to say to you.",
        prayer: ["El Roi, thank you that you see me.", "This is where I have come from, and where I feel I am going: …", "Open my eyes to see others the way you see them."],
        mission: { compass: "love", text: "This week, make a point of including someone who is usually on the edge: in a conversation, a game or a group." },
        journal: "Write about the ‘well’ Hagar didn’t see until God opened her eyes. Is there something good in your life you haven’t noticed? Ask God to open your eyes." }),
      af: own({ title: "Die God wat My Sien", bibleStory: "Genesis 16 & 21", readPassage: "Genesis 16:1–16 en 21:14–20",
        story: ["Genesis 16 is ’n ongemaklike hoofstuk. Sara, wat nie kinders kon kry nie, gee haar Egiptiese diensmeisie Hagar vir Abraham sodat Hagar vir haar ’n kind kan hê. Dit was toe ’n algemene gebruik, maar dit was nie God se plan nie, en dit loop sleg af. Hagar word swanger, spanning ontplof, en Sara mishandel haar totdat Hagar die woestyn in vlug.", "Dink aan Hagar se posisie: ’n vreemde slavevrou, swanger, alleen, sonder regte en sonder beskerming. Sy is deur ander gebruik en toe uitgestoot. In haar wêreld was sy die onbelangrikste persoon in die storie.", "Maar lees vers 7: ‘Die engel van die Here het Hagar by ’n fontein in die woestyn gekry.’ Die eerste keer dat ’n engel in die Bybel verskyn, kom hy nie na ’n koning of ’n aartsvader nie, maar na ’n weggeloopte slavin. God spreek haar op haar naam aan en vra twee vrae: ‘Waar kom jy vandaan, en waarheen gaan jy?’ God nooi haar om haar storie te vertel.", "Hy neem nie al haar probleme weg nie; Hy sê sy moet teruggaan. Maar Hy gee haar ’n belofte, ’n toekoms en ’n seun wie se naam, Ismael, ‘God hoor’ beteken. En Hagar antwoord met teologie uit haar eie ervaring: ‘U is die God wat my sien… Ek het nou die Een gesien wat my sien.’", "In hoofstuk 21, weer saam met Ismael verlaat, gaan sit sy om te huil, en ‘God het die seun hoor huil’. Hy het haar oë oopgemaak vir ’n put wat al die tyd daar was.", "Wat leer dit ons? God is nie net die God van die belangrike mense in die storie nie. Hy sien die oor-die-hoof-gesienes, die gebruiktes en die wat seerkry raak. As jy al ooit gebruik, uitgesluit of onsigbaar gevoel het, sien Hagar se God jou ook. En Hy roep sy volgelinge om die Hagars rondom hulle raak te sien."],
        verse: simple("U is die God wat my sien… Ek het nou die Een gesien wat my sien.", "Genesis 16:13"),
        lessons: ["God sien en sorg vir die oor-die-hoof-gesienes, die gebruiktes en die wat seerkry.", "God nooi ons om ons hele storie na Hom te bring: waar ons vandaan kom en waarheen ons gaan.", "God se volgelinge word geroep om die ‘Hagars’ rondom hulle raak te sien."],
        questions: ["Wat wys dit oor God dat die eerste engel in die Bybel aan ’n weggeloopte slavin verskyn?", "Het jy al ooit gebruik, uitgesluit of onsigbaar gevoel? Wat sê El Roi daaroor?", "Wie is ’n ‘Hagar’ in jou wêreld wat raakgesien moet word?"],
        listen: "Stel ’n tydhouer vir twee minute. Beantwoord God se twee vrae eerlik op skrif: ‘Waar kom jy vandaan? Waarheen gaan jy?’ Vra Hom dan wat Hy vir jou wil sê.",
        prayer: ["El Roi, dankie dat U my sien.", "Dit is waar ek vandaan kom, en waarheen ek voel ek gaan: …", "Maak my oë oop om ander te sien soos U hulle sien."],
        mission: { compass: "love", text: "Maak hierdie week ’n punt daarvan om iemand in te sluit wat gewoonlik op die kantlyn is: in ’n gesprek, ’n speletjie of ’n groep." },
        journal: "Skryf oor die ‘put’ wat Hagar nie gesien het totdat God haar oë oopgemaak het nie. Is daar iets goeds in jou lewe wat jy nie raakgesien het nie? Vra God om jou oë oop te maak." }),
    },
  },

  "j02-n02": {
    "8-9": {
      en: own({ title: "A Prayer at the Well", bibleStory: "Genesis 24", readPassage: "Genesis 24:10–27",
        story: ["Abraham wanted his son Isaac to marry someone who would share his faith in God. So he sent his oldest, most trusted servant on a journey of hundreds of kilometres back to his relatives, with ten camels and many gifts.", "When the servant arrived at the town well in the evening, he faced an impossible task: how do you choose the right person out of a whole town? So he did the wisest thing: he prayed. ‘Lord, God of my master Abraham, make me successful today.’ He asked God for a specific sign: the right young woman would offer water not only to him, but to his camels too.", "That was a big ask. A thirsty camel can drink up to a hundred litres of water, and there were ten of them! Whoever did that would be showing extraordinary kindness and hard work.", "‘Before he had finished praying, Rebekah came out with her jar on her shoulder.’ When the servant asked for a drink, she said, ‘Drink, my lord… I’ll draw water for your camels too, until they have had enough.’ She ran back and forth to the well until the job was done.", "The servant watched in amazement, then bowed down and worshipped: ‘Praise be to the Lord… As for me, the Lord has led me on the journey.’", "God still guides His children. Sometimes He answers dramatically; more often He leads step by step as we pray, trust Him and keep walking. Notice too that God used Rebekah’s ordinary kindness as part of His plan. Your kindness can be part of someone else’s answered prayer."],
        verse: simple("Trust in the Lord with all your heart… and He will make your paths straight.", "Proverbs 3:5–6"),
        lessons: ["God guides us when we pray and trust Him.", "God sometimes answers prayer before we have even finished praying!", "Our everyday kindness can be part of God’s plan for someone else."],
        questions: ["What sign did the servant ask God for? Why was it such a good test of character?", "How did Rebekah go beyond what was asked?", "What decision do you need God’s guidance for right now?"],
        listen: "Bring God a decision you need to make. Ask: ‘Lord, how do you want to guide me in this?’ Listen quietly, and write down what you sense.",
        prayer: ["Lord, thank you that you lead your children.", "Please guide me with…", "Help me to be kind like Rebekah, even when it’s hard work."],
        mission: { compass: "love", text: "Tomorrow, go beyond what is asked: when someone asks for a little help, give a lot." },
        journal: "Write down a decision you are facing. Write a prayer asking God to guide you, and leave space to write how He answers." }),
      af: own({ title: "’n Gebed by die Put", bibleStory: "Genesis 24", readPassage: "Genesis 24:10–27",
        story: ["Abraham wou hê sy seun Isak moet trou met iemand wat sy geloof in God sou deel. Toe stuur hy sy oudste, mees betroubare dienskneg op ’n reis van honderde kilometers terug na sy familie, met tien kamele en baie geskenke.", "Toe die dienskneg saans by die dorp se put aankom, het hy voor ’n onmoontlike taak gestaan: hoe kies jy die regte persoon uit ’n hele dorp? Toe het hy die wysste ding gedoen: hy het gebid. ‘Here, God van my meester Abraham, laat dit vandag vir my goed gaan.’ Hy het God vir ’n spesifieke teken gevra: die regte jong vrou sou nie net vir hom water aanbied nie, maar vir sy kamele ook.", "Dit was ’n groot versoek. ’n Dors kameel kan tot honderd liter water drink, en daar was tien van hulle! Wie dit ook al doen, sou buitengewone goedheid en harde werk wys.", "‘Voordat hy klaar gebid het, het Rebekka met haar kruik op haar skouer uitgekom.’ Toe die dienskneg vir ’n drinkie vra, het sy gesê: ‘Drink, meneer… Ek sal ook vir jou kamele water skep, totdat hulle genoeg gehad het.’ Sy het heen en weer na die put gehardloop totdat die werk klaar was.", "Die dienskneg het verwonderd gekyk, en toe gebuig en aanbid: ‘Prys die Here… Wat my betref, die Here het my op die reis gelei.’", "God lei vandag nog sy kinders. Soms antwoord Hy dramaties; meestal lei Hy tree vir tree terwyl ons bid, Hom vertrou en aanhou loop. Let ook op dat God Rebekka se gewone goedheid as deel van sy plan gebruik het. Jou goedheid kan deel wees van iemand anders se beantwoorde gebed."],
        verse: simple("Vertrou op die Here met jou hele hart… en Hy sal jou paaie gelyk maak.", "Spreuke 3:5–6"),
        lessons: ["God lei ons as ons bid en Hom vertrou.", "God antwoord soms gebed nog voordat ons klaar gebid het!", "Ons alledaagse goedheid kan deel wees van God se plan vir iemand anders."],
        questions: ["Watter teken het die dienskneg God voor gevra? Hoekom was dit so ’n goeie toets van karakter?", "Hoe het Rebekka meer gedoen as wat gevra is?", "Vir watter besluit het jy nou God se leiding nodig?"],
        listen: "Bring vir God ’n besluit wat jy moet neem. Vra: ‘Here, hoe wil U my hierin lei?’ Luister stil, en skryf neer wat jy aanvoel.",
        prayer: ["Here, dankie dat U u kinders lei.", "Lei my asseblief met…", "Help my om gaaf te wees soos Rebekka, selfs as dit harde werk is."],
        mission: { compass: "love", text: "Doen môre meer as wat gevra word: as iemand vir ’n bietjie hulp vra, gee baie." },
        journal: "Skryf ’n besluit neer waarvoor jy staan. Skryf ’n gebed waarin jy God vra om jou te lei, en laat plek om te skryf hoe Hy antwoord." }),
    },
    "10-12": {
      en: own({ title: "Guidance and Character", bibleStory: "Genesis 24", readPassage: "Genesis 24:1–27 and 24:50–58",
        story: ["Genesis 24 is the longest chapter in Genesis, and it is entirely about one question: how does God guide? Abraham’s servant has a huge responsibility: find a wife for Isaac from Abraham’s relatives, far away. He has no map, no app and no idea who he is looking for.", "Look at what he does. First, he prays specifically. He asks for a sign that is really a test of character: the right woman would generously offer to water ten thirsty camels, which would be at least an hour of exhausting work. He wasn’t asking God for a random coincidence. He was asking God to show him someone with a servant heart.", "Second, he watches and waits. Verse 21 says ‘without saying a word, the man watched her closely to learn whether or not the Lord had made his journey successful’. Guidance often involves patient observation, not rushing to conclusions.", "Third, when God answers, he worships immediately: ‘Praise be to the Lord… I have been on the journey, and the Lord has led me.’", "Then notice Rebekah. She is not a passive character. When asked, ‘Will you go with this man?’ she answers, ‘I will go.’ It took courage to leave everything for a family she had never met, trusting that God was in it.", "How does God guide us today? Mainly through His Word, which shows us His will in most situations. Through prayer and the peace of the Holy Spirit. Through wise people around us. And sometimes through circumstances that line up in remarkable ways. Usually guidance isn’t a dramatic voice telling us exactly what to do. It is God leading people who are walking closely with Him, one step at a time.", "Also notice that character mattered more than appearance. The servant wasn’t looking for the most beautiful or popular girl, but the kindest. God still values that most."],
        verse: simple("In all your ways submit to Him, and He will make your paths straight.", "Proverbs 3:6"),
        lessons: ["God guides people who pray, watch patiently and walk closely with Him.", "God usually guides through His Word, prayer, wise people and circumstances.", "Character, like a servant heart, matters more to God than appearance or popularity."],
        questions: ["What three things did the servant do to seek God’s guidance?", "Why was Rebekah’s ‘I will go’ an act of faith?", "What helps you know God’s guidance? What makes it harder?"],
        listen: "Set a timer for two minutes. Bring God a choice you are facing. Pray, then watch and wait quietly. Write down any thought, verse or sense of peace that comes.",
        prayer: ["Lord, I want to walk closely with you so you can guide me.", "Please lead me in my decision about…", "Give me a servant heart like Rebekah’s."],
        mission: { compass: "listen", text: "Before any big choice this week, follow the servant’s pattern: pray specifically, watch patiently, and thank God when He leads." },
        journal: "List the ways God has guided you in the past. Which way does He seem to use most in your life?" }),
      af: own({ title: "Leiding en Karakter", bibleStory: "Genesis 24", readPassage: "Genesis 24:1–27 en 24:50–58",
        story: ["Genesis 24 is die langste hoofstuk in Genesis, en dit gaan heeltemal oor een vraag: hoe lei God? Abraham se dienskneg het ’n groot verantwoordelikheid: kry ’n vrou vir Isak uit Abraham se familie, ver weg. Hy het geen kaart nie, geen toep nie, en geen idee na wie hy soek nie.", "Kyk wat hy doen. Eerstens bid hy spesifiek. Hy vra vir ’n teken wat eintlik ’n toets van karakter is: die regte vrou sou vrygewig aanbied om tien dors kamele water te gee, wat ten minste ’n uur se uitputtende werk sou wees. Hy het God nie vir ’n lukrake toeval gevra nie. Hy het God gevra om hom iemand met ’n diensbare hart te wys.", "Tweedens hou hy dop en wag. Vers 21 sê ‘sonder om ’n woord te sê, het die man haar noukeurig dopgehou om te weet of die Here sy reis laat slaag het of nie’. Leiding vra dikwels geduldige waarneming, nie om haastig gevolgtrekkings te maak nie.", "Derdens, toe God antwoord, aanbid hy dadelik: ‘Prys die Here… Ek was op die reis, en die Here het my gelei.’", "Let dan op Rebekka. Sy is nie ’n passiewe karakter nie. Toe sy gevra word: ‘Sal jy saam met hierdie man gaan?’ antwoord sy: ‘Ek sal gaan.’ Dit het moed gekos om alles agter te laat vir ’n familie wat sy nog nooit ontmoet het nie, en te vertrou dat God daarin was.", "Hoe lei God ons vandag? Hoofsaaklik deur sy Woord, wat ons in die meeste situasies sy wil wys. Deur gebed en die vrede van die Heilige Gees. Deur wyse mense rondom ons. En soms deur omstandighede wat op merkwaardige maniere inmekaarpas. Gewoonlik is leiding nie ’n dramatiese stem wat ons presies vertel wat om te doen nie. Dit is God wat mense lei wat naby Hom lewe, een tree op ’n slag.", "Let ook op dat karakter meer saak gemaak het as voorkoms. Die dienskneg het nie na die mooiste of gewildste meisie gesoek nie, maar na die gaafste. God ag dit vandag nog die meeste."],
        verse: simple("Erken Hom in alles wat jy doen, en Hy sal jou paaie gelyk maak.", "Spreuke 3:6"),
        lessons: ["God lei mense wat bid, geduldig dophou en naby Hom lewe.", "God lei gewoonlik deur sy Woord, gebed, wyse mense en omstandighede.", "Karakter, soos ’n diensbare hart, maak vir God meer saak as voorkoms of gewildheid."],
        questions: ["Watter drie dinge het die dienskneg gedoen om God se leiding te soek?", "Hoekom was Rebekka se ‘Ek sal gaan’ ’n daad van geloof?", "Wat help jou om God se leiding te ken? Wat maak dit moeiliker?"],
        listen: "Stel ’n tydhouer vir twee minute. Bring vir God ’n keuse waarvoor jy staan. Bid, hou dan stil dop en wag. Skryf enige gedagte, vers of gevoel van vrede neer wat kom.",
        prayer: ["Here, ek wil naby U lewe sodat U my kan lei.", "Lei my asseblief in my besluit oor…", "Gee my ’n diensbare hart soos Rebekka s’n."],
        mission: { compass: "listen", text: "Volg voor enige groot keuse hierdie week die dienskneg se patroon: bid spesifiek, hou geduldig dop, en dank God as Hy lei." },
        journal: "Lys die maniere waarop God jou in die verlede gelei het. Watter manier lyk dit of Hy die meeste in jou lewe gebruik?" }),
    },
  },

  "j02-n03": {
    "8-9": {
      en: own({ title: "The Peacemaker’s Wells", bibleStory: "Genesis 26", readPassage: "Genesis 26:12–25",
        story: ["Isaac doesn’t get as many stories as his father Abraham or his son Jacob, but Genesis 26 shows us something special about him: he was a peacemaker.", "God blessed Isaac so much that his crops produced a hundred times what he planted, and his flocks and herds grew huge. That made the Philistines jealous. They filled in his father’s old wells with earth, and the king told him to move away.", "In that dry land, wells were worth more than gold. When Isaac’s servants dug a new well and found fresh water, the local herdsmen argued: ‘The water is ours!’ Isaac named it Esek, which means ‘argument’, and moved on. They dug another, and the herders quarrelled again. He named it Sitnah, ‘opposition’, and moved on again.", "They dug a third well, and this time no one argued. Isaac called it Rehoboth, ‘room’, and said, ‘Now the Lord has given us room and we will flourish in the land.’", "That night God appeared to him: ‘Do not be afraid, for I am with you; I will bless you.’ Isaac built an altar and worshipped. Soon afterwards, the very king who had sent him away came to make a peace treaty, saying, ‘We saw clearly that the Lord was with you.’", "Isaac could have fought for his rights. Instead, he trusted God to provide. His peacemaking didn’t make him a loser; it made room for God to bless him, and even won over his enemies."],
        verse: simple("Blessed are the peacemakers, for they will be called children of God.", "Matthew 5:9"),
        lessons: ["Peacemakers trust God instead of fighting for everything.", "God makes room for His children when they trust Him.", "A peaceful life can win over even our opponents."],
        questions: ["What do the names Esek, Sitnah and Rehoboth mean? Why do you think Isaac chose them?", "Why might the king have changed his mind about Isaac?", "Where is a situation where you could choose peace instead of an argument?"],
        listen: "Be still and ask God: ‘Is there an argument you want me to walk away from, or a peace you want me to make?’ Listen and write down what you sense.",
        prayer: ["Lord, thank you that you make room for me.", "Help me to be a peacemaker with…", "I trust you to take care of me."],
        mission: { compass: "love", text: "This week, when an argument starts, choose to be the first to calm it down." },
        journal: "Draw three wells and label them Esek, Sitnah and Rehoboth. Next to each, write about a time in your life that feels like that well." }),
      af: own({ title: "Die Vredemaker se Putte", bibleStory: "Genesis 26", readPassage: "Genesis 26:12–25",
        story: ["Isak kry nie soveel stories soos sy pa Abraham of sy seun Jakob nie, maar Genesis 26 wys ons iets spesiaals van hom: hy was ’n vredemaker.", "God het Isak so baie geseën dat sy oeste honderd keer meer opgelewer het as wat hy geplant het, en sy troppe en kuddes het baie groot geword. Dit het die Filistyne jaloers gemaak. Hulle het sy pa se ou putte met grond toegegooi, en die koning het vir hom gesê om weg te trek.", "In daardie droë land was putte meer werd as goud. Toe Isak se diensknegte ’n nuwe put grawe en vars water kry, het die plaaslike veewagters gestry: ‘Die water is ons s’n!’ Isak het dit Esek genoem, wat ‘rusie’ beteken, en aangetrek. Hulle het nog een gegrawe, en die veewagters het weer gestry. Hy het dit Sitna genoem, ‘teenstand’, en weer aangetrek.", "Hulle het ’n derde put gegrawe, en hierdie keer het niemand gestry nie. Isak het dit Rehobot genoem, ‘ruimte’, en gesê: ‘Nou het die Here vir ons ruimte gegee en sal ons in die land voorspoedig wees.’", "Daardie nag het God aan hom verskyn: ‘Moenie bang wees nie, want Ek is by jou; Ek sal jou seën.’ Isak het ’n altaar gebou en aanbid. Kort daarna het die einste koning wat hom weggestuur het, gekom om ’n vredesverdrag te sluit, en gesê: ‘Ons het duidelik gesien dat die Here by jou is.’", "Isak kon vir sy regte baklei het. In plaas daarvan het hy God vertrou om te voorsien. Om vrede te maak het hom nie ’n verloorder gemaak nie; dit het plek gemaak vir God om hom te seën, en selfs sy vyande gewen."],
        verse: simple("Gelukkig is die wat vrede maak, want hulle sal kinders van God genoem word.", "Matteus 5:9"),
        lessons: ["Vredemakers vertrou God in plaas daarvan om vir alles te baklei.", "God maak plek vir sy kinders as hulle Hom vertrou.", "’n Vreedsame lewe kan selfs ons teenstanders wen."],
        questions: ["Wat beteken die name Esek, Sitna en Rehobot? Hoekom dink jy het Isak hulle gekies?", "Hoekom het die koning dalk van plan verander oor Isak?", "Waar is ’n situasie waar jy vrede kan kies in plaas van ’n argument?"],
        listen: "Wees stil en vra God: ‘Is daar ’n argument waarvan U wil hê ek moet wegstap, of vrede wat U wil hê ek moet maak?’ Luister en skryf neer wat jy aanvoel.",
        prayer: ["Here, dankie dat U vir my plek maak.", "Help my om vrede te maak met…", "Ek vertrou U om vir my te sorg."],
        mission: { compass: "love", text: "Kies hierdie week, as ’n argument begin, om die eerste een te wees wat dit kalmeer." },
        journal: "Teken drie putte en noem hulle Esek, Sitna en Rehobot. Skryf langs elkeen oor ’n tyd in jou lewe wat soos daardie put voel." }),
    },
    "10-12": {
      en: own({ title: "Strength Under Control", bibleStory: "Genesis 26, Matthew 5", readPassage: "Genesis 26:12–33 and Matthew 5:5–9",
        story: ["Genesis 26 tells a quiet story about water and quarrels that turns out to say a lot about strength.", "Isaac was not weak. By verse 13 he was ‘very wealthy’; so powerful, in fact, that the Philistine king Abimelek said, ‘You have become too powerful for us.’ Isaac could easily have defended his wells by force. Yet three times, when local herders claimed the water his servants had dug for, he moved on. He named the wells after his experiences: Esek (‘dispute’), Sitnah (‘opposition’), and finally Rehoboth (‘room’), where ‘they did not quarrel’.", "Was Isaac a pushover? No. This is what the Bible calls meekness: strength under control. A powerful horse that is gentle in its rider’s hands isn’t weak; it is trained. Isaac had the power to fight, and chose not to, because he trusted God to provide. Jesus said, ‘Blessed are the meek, for they will inherit the earth.’ Isaac literally ended up with room in the land.", "God confirmed Isaac’s choice that very night: ‘Do not be afraid, for I am with you.’ And notice what peacemaking did to his enemies. Abimelek came with his advisers and said, ‘We saw clearly that the Lord was with you.’ Isaac threw them a feast and made a peace treaty. That same day his servants found water at another well. Peace and provision arrived together.", "In a world where people fight hard for their rights, their image and the last word, especially online, Isaac’s story is countercultural. It doesn’t mean you never stand up for what is right. Justice matters, and sometimes we must speak up, especially for others. But it does mean you don’t have to win every argument to be secure. When your security is in God, you can afford to be generous.", "Jesus called peacemakers ‘children of God’. They look like their Father, the ultimate Peacemaker, who made peace with us through the cross."],
        verse: simple("Blessed are the meek, for they will inherit the earth… Blessed are the peacemakers, for they will be called children of God.", "Matthew 5:5, 9"),
        lessons: ["Meekness is not weakness; it is strength under control.", "When our security is in God, we don’t need to win every argument.", "Peacemakers look like their Father, who made peace with us through Jesus."],
        questions: ["What is the difference between meekness and weakness?", "When should we speak up for what is right, and when should we let something go?", "Where do you most often fight for ‘the last word’, at home, at school or online?"],
        listen: "Set a timer for two minutes. Ask God: ‘Is there a conflict where you want me to choose peace?’ Write down what you sense, and one step you could take.",
        prayer: ["Father, thank you for making peace with me through Jesus.", "Give me strength under control in…", "Make me a peacemaker who looks like you."],
        mission: { compass: "love", text: "This week, let someone else have the last word in a disagreement that doesn’t really matter, and pray for them instead." },
        journal: "Write about an argument you ‘won’ that you now wish you had handled differently. What would meekness have looked like?" }),
      af: own({ title: "Krag onder Beheer", bibleStory: "Genesis 26, Matteus 5", readPassage: "Genesis 26:12–33 en Matteus 5:5–9",
        story: ["Genesis 26 vertel ’n stil storie oor water en rusies wat baie blyk te sê oor krag.", "Isak was nie swak nie. Teen vers 13 was hy ‘baie ryk’; so magtig, inderdaad, dat die Filistynse koning Abimeleg gesê het: ‘Jy het te magtig vir ons geword.’ Isak kon maklik sy putte met geweld verdedig het. Tog het hy drie keer, toe plaaslike veewagters die water opeis waarvoor sy diensknegte gegrawe het, aangetrek. Hy het die putte na sy ervarings genoem: Esek (‘rusie’), Sitna (‘teenstand’), en eindelik Rehobot (‘ruimte’), waar ‘hulle nie gestry het nie’.", "Was Isak ’n swakkeling? Nee. Dit is wat die Bybel sagmoedigheid noem: krag onder beheer. ’n Sterk perd wat sag is in sy ruiter se hande, is nie swak nie; dit is geleer. Isak het die krag gehad om te baklei, en het gekies om dit nie te doen nie, omdat hy God vertrou het om te voorsien. Jesus het gesê: ‘Gelukkig is die sagmoediges, want hulle sal die aarde besit.’ Isak het letterlik met ruimte in die land geëindig.", "God het Isak se keuse daardie selfde nag bevestig: ‘Moenie bang wees nie, want Ek is by jou.’ En let op wat vrede maak aan sy vyande gedoen het. Abimeleg het met sy raadgewers gekom en gesê: ‘Ons het duidelik gesien dat die Here by jou is.’ Isak het vir hulle ’n fees gehou en ’n vredesverdrag gesluit. Daardie selfde dag het sy diensknegte water by nog ’n put gekry. Vrede en voorsiening het saam aangekom.", "In ’n wêreld waar mense hard baklei vir hulle regte, hulle beeld en die laaste woord, veral aanlyn, gaan Isak se storie teen die stroom in. Dit beteken nie jy staan nooit op vir wat reg is nie. Geregtigheid maak saak, en soms moet ons praat, veral vir ander. Maar dit beteken jy hoef nie elke argument te wen om veilig te voel nie. As jou sekuriteit in God is, kan jy bekostig om vrygewig te wees.", "Jesus het vredemakers ‘kinders van God’ genoem. Hulle lyk soos hulle Vader, die grootste Vredemaker, wat deur die kruis vrede met ons gemaak het."],
        verse: simple("Gelukkig is die sagmoediges, want hulle sal die aarde besit… Gelukkig is die wat vrede maak, want hulle sal kinders van God genoem word.", "Matteus 5:5, 9"),
        lessons: ["Sagmoedigheid is nie swakheid nie; dit is krag onder beheer.", "As ons sekuriteit in God is, hoef ons nie elke argument te wen nie.", "Vredemakers lyk soos hulle Vader, wat deur Jesus vrede met ons gemaak het."],
        questions: ["Wat is die verskil tussen sagmoedigheid en swakheid?", "Wanneer moet ons opstaan vir wat reg is, en wanneer moet ons iets laat gaan?", "Waar baklei jy die meeste vir ‘die laaste woord’, by die huis, by die skool of aanlyn?"],
        listen: "Stel ’n tydhouer vir twee minute. Vra God: ‘Is daar ’n konflik waar U wil hê ek vrede moet kies?’ Skryf neer wat jy aanvoel, en een tree wat jy kan neem.",
        prayer: ["Vader, dankie dat U deur Jesus vrede met my gemaak het.", "Gee my krag onder beheer in…", "Maak my ’n vredemaker wat soos U lyk."],
        mission: { compass: "love", text: "Laat hierdie week iemand anders die laaste woord hê in ’n meningsverskil wat nie regtig saak maak nie, en bid eerder vir hulle." },
        journal: "Skryf oor ’n argument wat jy ‘gewen’ het wat jy nou wens jy anders hanteer het. Hoe sou sagmoedigheid gelyk het?" }),
    },
  },

  "j02-n04": {
    "8-9": {
      en: own({ title: "Surely the Lord Is in This Place", bibleStory: "Genesis 28", readPassage: "Genesis 28:10–22",
        story: ["Jacob had deceived his blind father and stolen the blessing meant for his brother Esau. Esau was so angry that he planned to kill him. So Jacob fled, leaving home with nothing but a staff in his hand.", "As the sun set, he stopped in an empty place, put a stone under his head and lay down to sleep. He was alone, guilty and afraid of the future.", "Then he dreamed. A stairway stood on the earth, its top reaching heaven, and angels were going up and down on it. Above it stood the Lord, who said: ‘I am the Lord, the God of your father Abraham and the God of Isaac… I am with you and will watch over you wherever you go… I will not leave you until I have done what I have promised you.’", "Notice what God didn’t say. He didn’t say, ‘Now that you’ve cheated your family, you’re on your own.’ God came to Jacob at his lowest point with grace, not condemnation. That doesn’t mean what Jacob did was okay; God would deal with Jacob’s character over many years. But God’s first word to the runaway was a promise.", "Jacob woke and said, ‘Surely the Lord is in this place, and I was not aware of it.’ He called the place Bethel, ‘house of God’.", "Centuries later, Jesus told Nathanael that he would see ‘heaven open, and the angels of God ascending and descending on the Son of Man’. Jesus is the true stairway between heaven and earth. Through Him, God comes close to us, wherever we are."],
        verse: simple("I am with you and will watch over you wherever you go.", "Genesis 28:15"),
        lessons: ["God is present even in lonely, unexpected places.", "God meets us with grace, even at our lowest point.", "Jesus is the true stairway, connecting heaven and earth."],
        questions: ["How do you think Jacob felt before and after his dream?", "Why do you think God was kind to Jacob even though he had done wrong?", "Where is a place you need to remember ‘Surely the Lord is in this place’?"],
        listen: "Be still and say, ‘Surely the Lord is in this place.’ Ask God: ‘How are you with me right here?’ Listen and write down what you sense.",
        prayer: ["Lord, you are with me wherever I go.", "Thank you for meeting me with grace, even when…", "Thank you that Jesus brings heaven close."],
        mission: { compass: "trust", text: "Tomorrow, wherever you go, pause and say quietly, ‘Surely the Lord is in this place.’" },
        journal: "Draw Jacob’s stairway. At the bottom, write a place where you feel lonely or unsure. At the top, write God’s promise from Genesis 28:15." }),
      af: own({ title: "Die Here Is Regtig op Hierdie Plek", bibleStory: "Genesis 28", readPassage: "Genesis 28:10–22",
        story: ["Jakob het sy blinde pa bedrieg en die seën gesteel wat vir sy broer Esau bedoel was. Esau was so kwaad dat hy beplan het om hom dood te maak. Toe het Jakob gevlug, en die huis verlaat met niks behalwe ’n kierie in sy hand nie.", "Toe die son ondergaan, het hy op ’n leë plek stilgehou, ’n klip onder sy kop gesit en gaan lê om te slaap. Hy was alleen, skuldig en bang vir die toekoms.", "Toe het hy gedroom. ’n Trap het op die aarde gestaan, met die bopunt tot in die hemel, en engele het daarop op en af gegaan. Bo-aan het die Here gestaan, en gesê: ‘Ek is die Here, die God van jou vader Abraham en die God van Isak… Ek is by jou en Ek sal oor jou waak oral waar jy gaan… Ek sal jou nie verlaat voordat Ek gedoen het wat Ek jou belowe het nie.’", "Let op wat God nie gesê het nie. Hy het nie gesê: ‘Nou dat jy jou familie gekul het, is jy op jou eie nie.’ God het na Jakob gekom op sy laagste punt, met genade, nie veroordeling nie. Dit beteken nie wat Jakob gedoen het, was reg nie; God sou oor baie jare met Jakob se karakter werk. Maar God se eerste woord aan die weghardloper was ’n belofte.", "Jakob het wakker geword en gesê: ‘Die Here is regtig op hierdie plek, en ek het dit nie geweet nie.’ Hy het die plek Bet-El genoem, ‘huis van God’.", "Eeue later het Jesus vir Natanael gesê dat hy ‘die hemel oop sal sien, en die engele van God wat opklim en neerdaal op die Seun van die mens’. Jesus is die ware trap tussen hemel en aarde. Deur Hom kom God naby aan ons, waar ons ook al is."],
        verse: simple("Ek is by jou en Ek sal oor jou waak oral waar jy gaan.", "Genesis 28:15"),
        lessons: ["God is teenwoordig selfs op eensame, onverwagte plekke.", "God ontmoet ons met genade, selfs op ons laagste punt.", "Jesus is die ware trap wat hemel en aarde verbind."],
        questions: ["Hoe dink jy het Jakob voor en ná sy droom gevoel?", "Hoekom dink jy was God goed vir Jakob al het hy verkeerd gedoen?", "Waar is ’n plek waar jy moet onthou ‘Die Here is regtig op hierdie plek’?"],
        listen: "Wees stil en sê: ‘Die Here is regtig op hierdie plek.’ Vra God: ‘Hoe is U hier by my?’ Luister en skryf neer wat jy aanvoel.",
        prayer: ["Here, U is by my oral waar ek gaan.", "Dankie dat U my met genade ontmoet, selfs wanneer…", "Dankie dat Jesus die hemel naby bring."],
        mission: { compass: "trust", text: "Gaan môre staan, oral waar jy gaan, en sê saggies: ‘Die Here is regtig op hierdie plek.’" },
        journal: "Teken Jakob se trap. Skryf onderaan ’n plek waar jy eensaam of onseker voel. Skryf bo-aan God se belofte uit Genesis 28:15." }),
    },
    "10-12": {
      en: own({ title: "Grace for a Runaway", bibleStory: "Genesis 27 – 28, John 1", readPassage: "Genesis 28:10–22 and John 1:47–51",
        story: ["Jacob is one of the most complicated characters in the Bible. He grasped his twin brother’s heel at birth. He bargained Esau out of his birthright for a bowl of stew. Then, with his mother’s help, he dressed up as Esau and lied to his blind father to steal the family blessing. When Esau vowed to kill him, Jacob fled.", "So when Jacob lies down alone at Bethel with a stone for a pillow, he is reaping what he has sown: guilt, fear and isolation. This is exactly the moment God chooses to show up.", "In his dream Jacob sees a stairway (or ramp) connecting earth and heaven, with angels ascending and descending, and the Lord standing above it. God repeats to Jacob the promises He made to Abraham: land, descendants, and that ‘all peoples on earth will be blessed through you and your offspring’. Then He adds something personal: ‘I am with you and will watch over you wherever you go… I will not leave you.’", "This is grace: undeserved favour. Jacob hadn’t repented yet. He hadn’t made things right with Esau. His character still needed years of work (and God would wrestle with him later!). But God’s commitment to him didn’t depend on his performance.", "Jacob’s response is honest but a little transactional: ‘If God will be with me… then the Lord will be my God.’ He is still a bargainer! God would patiently grow him from there.", "Jesus connected this story to Himself. He told Nathanael: ‘You will see heaven open, and the angels of God ascending and descending on the Son of Man.’ Jesus is the stairway. Heaven and earth meet in Him. We don’t climb up to God by our goodness; God comes down to us in Jesus.", "Whatever you have done, wherever you are running, God’s first word to you through Jesus is not ‘You’re on your own’, but ‘I am with you.’"],
        verse: simple("I am with you and will watch over you wherever you go… I will not leave you.", "Genesis 28:15"),
        lessons: ["Grace is God’s undeserved favour; it meets us before we have it all together.", "God patiently grows our character over time.", "Jesus is the stairway between heaven and earth: God comes down to us in Him."],
        questions: ["What had Jacob done to end up alone at Bethel?", "Why is it significant that God made His promise before Jacob changed?", "How does Jesus’ claim in John 1:51 change the way you read Jacob’s dream?"],
        listen: "Set a timer for two minutes. Picture the stairway with Jesus as the connection between you and heaven. Ask: ‘Lord, what do you want to say to me where I am right now?’ Write it down.",
        prayer: ["God, thank you for your grace, which reaches me before I have it all together.", "Keep growing my character, especially in…", "Thank you that in Jesus, heaven has come close to me."],
        mission: { compass: "trust", text: "This week, when you feel you have messed up, instead of hiding, pray: ‘Thank you that you are still with me.’" },
        journal: "Jacob tried to bargain with God (‘If you… then I…’). Write about any ways you try to bargain with God. How is grace different?" }),
      af: own({ title: "Genade vir ’n Weghardloper", bibleStory: "Genesis 27 – 28, Johannes 1", readPassage: "Genesis 28:10–22 en Johannes 1:47–51",
        story: ["Jakob is een van die mees ingewikkelde karakters in die Bybel. Hy het by sy geboorte sy tweelingbroer se hakskeen gegryp. Hy het Esau se eersgeboortereg vir ’n bord bredie afgeding. Toe het hy, met sy ma se hulp, soos Esau aangetrek en vir sy blinde pa gelieg om die familieseën te steel. Toe Esau sweer om hom dood te maak, het Jakob gevlug.", "So wanneer Jakob alleen by Bet-El gaan lê met ’n klip as kussing, oes hy wat hy gesaai het: skuld, vrees en isolasie. Dit is presies die oomblik wat God kies om op te daag.", "In sy droom sien Jakob ’n trap (of opritbaan) wat aarde en hemel verbind, met engele wat opklim en neerdaal, en die Here wat bo-aan staan. God herhaal vir Jakob die beloftes wat Hy aan Abraham gemaak het: land, nakomelinge, en dat ‘al die volke van die aarde deur jou en jou nageslag geseën sal word’. Dan voeg Hy iets persoonliks by: ‘Ek is by jou en Ek sal oor jou waak oral waar jy gaan… Ek sal jou nie verlaat nie.’", "Dit is genade: onverdiende guns. Jakob het hom nog nie bekeer nie. Hy het nog nie dinge met Esau reggemaak nie. Sy karakter het nog jare se werk nodig gehad (en God sou later met hom stoei!). Maar God se toewyding aan hom het nie van sy prestasie afgehang nie.", "Jakob se reaksie is eerlik, maar ’n bietjie soos ’n ooreenkoms: ‘As God by my is… dan sal die Here my God wees.’ Hy is nog steeds ’n onderhandelaar! God sou hom van daar af geduldig laat groei.", "Jesus het hierdie storie met Homself verbind. Hy het vir Natanael gesê: ‘Julle sal die hemel oop sien, en die engele van God wat opklim en neerdaal op die Seun van die mens.’ Jesus is die trap. Hemel en aarde ontmoet mekaar in Hom. Ons klim nie deur ons goedheid na God op nie; God kom in Jesus na ons af.", "Wat jy ook al gedoen het, waarheen jy ook al weghardloop, God se eerste woord aan jou deur Jesus is nie ‘Jy is op jou eie’ nie, maar ‘Ek is by jou.’"],
        verse: simple("Ek is by jou en Ek sal oor jou waak oral waar jy gaan… Ek sal jou nie verlaat nie.", "Genesis 28:15"),
        lessons: ["Genade is God se onverdiende guns; dit ontmoet ons voordat ons alles reg het.", "God laat ons karakter geduldig oor tyd groei.", "Jesus is die trap tussen hemel en aarde: God kom in Hom na ons af."],
        questions: ["Wat het Jakob gedoen om alleen by Bet-El te beland?", "Hoekom is dit betekenisvol dat God sy belofte gemaak het voordat Jakob verander het?", "Hoe verander Jesus se uitspraak in Johannes 1:51 die manier waarop jy Jakob se droom lees?"],
        listen: "Stel ’n tydhouer vir twee minute. Stel jou die trap voor met Jesus as die verbinding tussen jou en die hemel. Vra: ‘Here, wat wil U vir my sê waar ek nou is?’ Skryf dit neer.",
        prayer: ["God, dankie vir u genade, wat my bereik voordat ek alles reg het.", "Laat my karakter aanhou groei, veral in…", "Dankie dat die hemel in Jesus naby aan my gekom het."],
        mission: { compass: "trust", text: "As jy hierdie week voel jy het iets opgemors, bid eerder as om weg te kruip: ‘Dankie dat U steeds by my is.’" },
        journal: "Jakob het probeer om met God te onderhandel (‘As U… dan sal ek…’). Skryf oor enige maniere waarop jy met God probeer onderhandel. Hoe is genade anders?" }),
    },
  },

  "j02-n05": {
    "8-9": {
      en: own({ title: "Wrestling with God", bibleStory: "Genesis 32", readPassage: "Genesis 32:22–32",
        story: ["After twenty years away, Jacob was finally heading home, with his wives, children and flocks. But news came that his brother Esau was coming to meet him with four hundred men. Jacob was terrified.", "He did two things. He planned: he sent waves of gifts ahead to soften Esau’s anger. And he prayed one of the most honest prayers in Genesis: ‘I am unworthy of all the kindness and faithfulness you have shown your servant… Save me, I pray, from the hand of my brother Esau, for I am afraid.’", "That night, alone by the Jabbok River, a man wrestled with him until daybreak. When the man saw that he couldn’t win, he touched Jacob’s hip so that it was wrenched out of its socket. But Jacob still held on: ‘I will not let you go unless you bless me.’", "‘What is your name?’ the man asked. It was a painful question, because ‘Jacob’ was connected with grasping and deceiving. Saying his name was like admitting who he had been.", "Then came the blessing: ‘Your name will no longer be Jacob, but Israel, because you have struggled with God and with humans and have overcome.’ Jacob realised: ‘I saw God face to face, and yet my life was spared.’ He limped as the sun rose, a changed man.", "Sometimes our relationship with God includes wrestling: with hard questions, with our own pride or with things we don’t understand. God isn’t offended by that. Hold on to Him. He uses the struggle to change us, and He gives us a new name."],
        verse: simple("I will not let you go unless you bless me.", "Genesis 32:26"),
        lessons: ["God welcomes honest prayers, even prayers full of fear.", "God uses our struggles to change our character.", "God gives His children a new identity."],
        questions: ["What did Jacob do when he was afraid? What can we learn from his prayer?", "Why was it important for Jacob to say his name?", "What is something you are ‘wrestling’ with God about right now?"],
        listen: "Bring God something you are struggling with. Hold on to Him in prayer. Ask: ‘How do you want to bless me through this?’ Listen and write it down.",
        prayer: ["God, I won’t let go of you.", "I am wrestling with…", "Thank you for giving me a new name as your child."],
        mission: { compass: "trust", text: "If something worries you this week, write an honest prayer like Jacob’s: tell God exactly how you feel, and ask Him to help." },
        journal: "Write your own honest prayer like Jacob’s in Genesis 32:9–12: admit your fear, thank God for His kindness, and ask for His help." }),
      af: own({ title: "Stoei met God", bibleStory: "Genesis 32", readPassage: "Genesis 32:22–32",
        story: ["Ná twintig jaar weg was Jakob eindelik op pad huis toe, met sy vroue, kinders en troppe. Maar nuus het gekom dat sy broer Esau hom met vierhonderd mans tegemoet kom. Jakob was doodbang.", "Hy het twee dinge gedoen. Hy het beplan: hy het golwe geskenke vooruit gestuur om Esau se woede te versag. En hy het een van die eerlikste gebede in Genesis gebid: ‘Ek is nie werd al die goedheid en trou wat U aan u dienaar bewys het nie… Red my tog uit die hand van my broer Esau, want ek is bang.’", "Daardie nag, alleen by die Jabbokrivier, het ’n man met hom gestoei tot dagbreek. Toe die man sien hy kan nie wen nie, het hy aan Jakob se heup geraak sodat dit uit lit geruk is. Maar Jakob het steeds vasgehou: ‘Ek sal jou nie laat gaan voordat jy my seën nie.’", "‘Wat is jou naam?’ het die man gevra. Dit was ’n pynlike vraag, want ‘Jakob’ was verbind met gryp en bedrieg. Om sy naam te sê, was soos om te erken wie hy was.", "Toe kom die seën: ‘Jou naam sal nie meer Jakob wees nie, maar Israel, want jy het met God en met mense gestoei en jy het oorwin.’ Jakob het besef: ‘Ek het God van aangesig tot aangesig gesien, en tog het ek bly lewe.’ Hy het mank geloop toe die son opkom, ’n veranderde man.", "Soms sluit ons verhouding met God stoei in: met moeilike vrae, met ons eie trots of met dinge wat ons nie verstaan nie. God is nie daardeur beledig nie. Hou aan Hom vas. Hy gebruik die stryd om ons te verander, en Hy gee ons ’n nuwe naam."],
        verse: simple("Ek sal jou nie laat gaan voordat jy my seën nie.", "Genesis 32:26"),
        lessons: ["God verwelkom eerlike gebede, selfs gebede vol vrees.", "God gebruik ons stryd om ons karakter te verander.", "God gee sy kinders ’n nuwe identiteit."],
        questions: ["Wat het Jakob gedoen toe hy bang was? Wat kan ons uit sy gebed leer?", "Hoekom was dit belangrik vir Jakob om sy naam te sê?", "Waaroor ‘stoei’ jy nou met God?"],
        listen: "Bring vir God iets waarmee jy sukkel. Hou in gebed aan Hom vas. Vra: ‘Hoe wil U my hierdeur seën?’ Luister en skryf dit neer.",
        prayer: ["God, ek sal U nie los nie.", "Ek stoei met…", "Dankie dat U my ’n nuwe naam as u kind gee."],
        mission: { compass: "trust", text: "As iets jou hierdie week bekommer, skryf ’n eerlike gebed soos Jakob s’n: vertel God presies hoe jy voel, en vra Hom om te help." },
        journal: "Skryf jou eie eerlike gebed soos Jakob s’n in Genesis 32:9–12: erken jou vrees, dank God vir sy goedheid, en vra vir sy hulp." }),
    },
    "10-12": {
      en: own({ title: "The Limp and the Name", bibleStory: "Genesis 32", readPassage: "Genesis 32:1–32",
        story: ["Genesis 32 is one of the strangest and most profound chapters in the Bible. Jacob, the lifelong schemer, is about to meet the brother he cheated. Esau is coming with four hundred men, and Jacob assumes the worst.", "First, notice Jacob’s prayer in verses 9–12. It is the first time we hear him pray with real humility: ‘I am unworthy of all the kindness and faithfulness you have shown your servant.’ Then he is completely honest: ‘I am afraid.’ Fear brought Jacob to his knees, and that’s often where God begins His deepest work in us.", "Then, alone at night by the river, ‘a man wrestled with him till daybreak’. The text gradually reveals who this is: Jacob later says, ‘I saw God face to face.’ The prophet Hosea calls him an angel. Many Christians have seen here a pre-incarnate appearance of God the Son.", "Think about the symbolism. Jacob has wrestled with people all his life, grasping for blessings, outmanoeuvring his brother and his uncle. Now he wrestles with God Himself, and he cannot win by tricks. God touches his hip, and Jacob is injured. Yet he clings on: ‘I will not let you go unless you bless me.’ He has finally realised that the blessing he needs can’t be stolen; it must be received from God.", "Before blessing him, God asks: ‘What is your name?’ To say ‘Jacob’ is to confess ‘deceiver’. Real change starts with honest confession. Then God gives him a new name, Israel, and a new identity.", "Jacob walks away limping. That limp is important. God’s deepest blessings often come through weakness, not around it. Paul later wrote that God told him, ‘My power is made perfect in weakness.’", "If you are wrestling with God, with questions, with sin or with pain, don’t let go. The struggle may leave a limp, but it can also bring a new name."],
        verse: simple("My grace is sufficient for you, for my power is made perfect in weakness.", "2 Corinthians 12:9"),
        lessons: ["Fear and honesty often bring us to the place where God does His deepest work.", "Real change begins with honest confession of who we have been.", "God’s blessings often come through our weakness, not around it."],
        questions: ["What is different about Jacob’s prayer in verses 9–12 compared to his earlier bargaining at Bethel?", "Why do you think God asked Jacob his name?", "What weakness or ‘limp’ in your life might God want to use?"],
        listen: "Set a timer for two minutes. Tell God honestly what you are wrestling with. Then ask: ‘What new name do you want to give me?’ Write down what you sense.",
        prayer: ["God, I am unworthy of your kindness, and I am honest about my fear of…", "I won’t let go until you bless me.", "Thank you that your power is made perfect in my weakness."],
        mission: { compass: "talk", text: "Write your own Genesis 32:9–12 prayer this week: humble, honest and specific." },
        journal: "Write your old ‘name’ (a word that describes who you have sometimes been) and the new name God gives you in Christ. What changes when you live from the new one?" }),
      af: own({ title: "Die Mank Been en die Naam", bibleStory: "Genesis 32", readPassage: "Genesis 32:1–32",
        story: ["Genesis 32 is een van die vreemdste en diepste hoofstukke in die Bybel. Jakob, die lewenslange planmaker, staan op die punt om die broer te ontmoet wat hy bedrieg het. Esau kom met vierhonderd mans, en Jakob verwag die ergste.", "Let eers op Jakob se gebed in verse 9–12. Dit is die eerste keer dat ons hom met ware nederigheid hoor bid: ‘Ek is nie werd al die goedheid en trou wat U aan u dienaar bewys het nie.’ Dan is hy heeltemal eerlik: ‘Ek is bang.’ Vrees het Jakob op sy knieë gebring, en dit is dikwels waar God sy diepste werk in ons begin.", "Dan, alleen in die nag by die rivier, ‘het ’n man met hom gestoei tot dagbreek’. Die teks wys geleidelik wie dit is: Jakob sê later: ‘Ek het God van aangesig tot aangesig gesien.’ Die profeet Hosea noem hom ’n engel. Baie Christene het hier ’n verskyning van God die Seun gesien voordat Hy mens geword het.", "Dink aan die simboliek. Jakob het sy hele lewe lank met mense gestoei, na seëninge gegryp, sy broer en sy oom uitoorlê. Nou stoei hy met God self, en hy kan nie met truuks wen nie. God raak aan sy heup, en Jakob word beseer. Tog klou hy vas: ‘Ek sal jou nie laat gaan voordat jy my seën nie.’ Hy het eindelik besef dat die seën wat hy nodig het, nie gesteel kan word nie; dit moet van God ontvang word.", "Voordat Hy hom seën, vra God: ‘Wat is jou naam?’ Om ‘Jakob’ te sê, is om ‘bedrieër’ te bely. Ware verandering begin met eerlike belydenis. Dan gee God hom ’n nuwe naam, Israel, en ’n nuwe identiteit.", "Jakob stap mank weg. Daardie mank been is belangrik. God se diepste seëninge kom dikwels deur swakheid, nie om dit nie. Paulus het later geskryf dat God vir hom gesê het: ‘My krag kom juis tot volle werking wanneer jy swak is.’", "As jy met God stoei, met vrae, met sonde of met pyn, moenie los nie. Die stryd laat jou dalk mank, maar dit kan ook ’n nuwe naam bring."],
        verse: simple("My genade is vir jou genoeg, want my krag kom juis tot volle werking wanneer jy swak is.", "2 Korintiërs 12:9"),
        lessons: ["Vrees en eerlikheid bring ons dikwels na die plek waar God sy diepste werk doen.", "Ware verandering begin met eerlike belydenis van wie ons was.", "God se seëninge kom dikwels deur ons swakheid, nie om dit nie."],
        questions: ["Wat is anders aan Jakob se gebed in verse 9–12 as sy vroeëre onderhandeling by Bet-El?", "Hoekom dink jy het God Jakob sy naam gevra?", "Watter swakheid of ‘mank been’ in jou lewe wil God dalk gebruik?"],
        listen: "Stel ’n tydhouer vir twee minute. Vertel God eerlik waarmee jy stoei. Vra dan: ‘Watter nuwe naam wil U my gee?’ Skryf neer wat jy aanvoel.",
        prayer: ["God, ek is u goedheid nie werd nie, en ek is eerlik oor my vrees vir…", "Ek sal nie los voordat U my seën nie.", "Dankie dat u krag in my swakheid tot volle werking kom."],
        mission: { compass: "talk", text: "Skryf hierdie week jou eie Genesis 32:9–12-gebed: nederig, eerlik en spesifiek." },
        journal: "Skryf jou ou ‘naam’ (’n woord wat beskryf wie jy soms was) en die nuwe naam wat God jou in Christus gee. Wat verander as jy uit die nuwe een lewe?" }),
    },
  },

  "j02-n06": {
    "8-9": {
      en: own({ title: "Running to Forgive", bibleStory: "Genesis 33", readPassage: "Genesis 33:1–11",
        story: ["The sun was up, Jacob was limping, and there on the horizon was Esau with four hundred men. Jacob arranged his family behind him and went ahead, bowing to the ground seven times as he approached his brother. In that culture, it was how a servant approached a king. Jacob, who had once grabbed the blessing, was now humbling himself.", "Then the unexpected happened. ‘Esau ran to meet Jacob and embraced him; he threw his arms around his neck and kissed him. And they wept.’ The brother who had been wronged, who had every reason for revenge, ran to forgive.", "Does that remind you of another story? Jesus told of a father who saw his runaway son from a long way off, ‘ran to his son, threw his arms around him and kissed him’. The words are almost exactly the same! Jesus may have had Esau in mind. Forgiveness that runs is a picture of God’s own heart.", "Jacob insisted that Esau keep the gifts and said something remarkable: ‘To see your face is like seeing the face of God, now that you have received me favourably.’ When we experience forgiveness, we catch a glimpse of what God is like.", "Forgiveness doesn’t pretend that what happened didn’t matter. Esau had been badly hurt. But he chose not to hold it over his brother any longer. And God had been at work in both brothers’ hearts during those twenty years.", "Is there someone you need to forgive, or someone you need to ask for forgiveness? With God’s help, it is possible."],
        verse: simple("Be kind and compassionate to one another, forgiving each other, just as in Christ God forgave you.", "Ephesians 4:32"),
        lessons: ["Forgiveness that runs towards others is a picture of God’s heart.", "Humility and saying sorry open the door to peace.", "God works in hearts over time to make reconciliation possible."],
        questions: ["How did Jacob approach Esau? What did that show?", "What is similar between Esau and the father in Jesus’ story of the lost son?", "Is there someone you need to forgive, or to ask forgiveness from?"],
        listen: "Be still and ask God: ‘Is there someone you want me to forgive, or say sorry to?’ Listen. Then ask Him for the strength to do it.",
        prayer: ["Father, thank you for running to forgive me.", "Help me to forgive… / to say sorry to…", "Make me someone who makes peace."],
        mission: { compass: "love", text: "Take one step this week towards making peace with someone: a message, an apology or a kind act." },
        journal: "Compare Genesis 33:4 with Luke 15:20. Write what both verses teach you about forgiveness." }),
      af: own({ title: "Hardloop om te Vergewe", bibleStory: "Genesis 33", readPassage: "Genesis 33:1–11",
        story: ["Die son was op, Jakob het mank geloop, en daar op die horison was Esau met vierhonderd mans. Jakob het sy familie agter hom gerangskik en vooruit gegaan, en sewe keer tot op die grond gebuig terwyl hy nader aan sy broer kom. In daardie kultuur het ’n dienskneg so na ’n koning toe gegaan. Jakob, wat eens die seën gegryp het, het homself nou verneder.", "Toe het die onverwagte gebeur. ‘Esau het Jakob tegemoet gehardloop en hom omhels; hy het sy arms om sy nek gegooi en hom gesoen. En hulle het gehuil.’ Die broer wat verontreg is, wat elke rede vir wraak gehad het, het gehardloop om te vergewe.", "Herinner dit jou aan ’n ander storie? Jesus het vertel van ’n vader wat sy weggeloopte seun van ver af gesien het, ‘na sy seun toe gehardloop het, sy arms om hom gegooi en hom gesoen het’. Die woorde is amper presies dieselfde! Jesus het dalk aan Esau gedink. Vergifnis wat hardloop, is ’n prentjie van God se eie hart.", "Jakob het daarop aangedring dat Esau die geskenke hou, en iets merkwaardigs gesê: ‘Om jou gesig te sien, is soos om die gesig van God te sien, noudat jy my so goed ontvang het.’ As ons vergifnis ervaar, kry ons ’n kykie in hoe God is.", "Vergifnis maak nie of wat gebeur het nie saak gemaak het nie. Esau is erg seergemaak. Maar hy het gekies om dit nie langer teen sy broer te hou nie. En God was in daardie twintig jaar in albei broers se harte aan die werk.", "Is daar iemand wat jy moet vergewe, of iemand wat jy om vergifnis moet vra? Met God se hulp is dit moontlik."],
        verse: simple("Wees goed en vol deernis teenoor mekaar, en vergewe mekaar soos God julle in Christus vergewe het.", "Efesiërs 4:32"),
        lessons: ["Vergifnis wat na ander toe hardloop, is ’n prentjie van God se hart.", "Nederigheid en jammer sê maak die deur oop vir vrede.", "God werk oor tyd in harte om versoening moontlik te maak."],
        questions: ["Hoe het Jakob na Esau toe gegaan? Wat het dit gewys?", "Wat is soortgelyk tussen Esau en die vader in Jesus se storie van die verlore seun?", "Is daar iemand wat jy moet vergewe, of iemand vir wie jy om vergifnis moet vra?"],
        listen: "Wees stil en vra God: ‘Is daar iemand wat U wil hê ek moet vergewe, of vir wie ek jammer moet sê?’ Luister. Vra Hom dan vir die krag om dit te doen.",
        prayer: ["Vader, dankie dat U gehardloop het om my te vergewe.", "Help my om… te vergewe / om vir… jammer te sê.", "Maak my iemand wat vrede maak."],
        mission: { compass: "love", text: "Neem hierdie week een tree om vrede met iemand te maak: ’n boodskap, ’n verskoning of ’n gawe daad." },
        journal: "Vergelyk Genesis 33:4 met Lukas 15:20. Skryf wat albei verse jou oor vergifnis leer." }),
    },
    "10-12": {
      en: own({ title: "The Face of God in a Brother", bibleStory: "Genesis 33, Luke 15", readPassage: "Genesis 33:1–17 and Luke 15:20",
        story: ["After twenty years, a night of wrestling and a new name, Jacob meets Esau. The scene is carefully written, and it rewards slow reading.", "Jacob goes ahead of his family and ‘bowed down to the ground seven times as he approached his brother’. This is a deliberate reversal. Years earlier, Jacob had stolen a blessing that said, ‘May your mother’s sons bow down to you.’ Now Jacob bows to Esau. Repentance often looks like undoing, as far as we can, the damage our pride has caused.", "Then: ‘Esau ran to meet Jacob and embraced him; he threw his arms around his neck and kissed him. And they wept.’ Read Luke 15:20, the father welcoming the prodigal: ‘He ran to his son, threw his arms around him and kissed him.’ The parallel is striking. In Jesus’ story, the running, embracing figure represents God the Father.", "Jacob then says something theologically rich: ‘To see your face is like seeing the face of God, now that you have received me favourably.’ He had just seen God face to face at the river. Now, in his brother’s undeserved welcome, he sees God’s character again. Grace given by people reflects the grace of God.", "But the story is also realistic. The brothers reconcile, yet they don’t move in together. Jacob politely declines to travel with Esau and settles elsewhere. Forgiveness and reconciliation are real, but restoring trust and closeness can take time, and sometimes healthy boundaries remain. That is not failure. It is wisdom.", "What does this mean for you? First, you can receive God’s forgiveness as freely as Jacob received Esau’s welcome. Second, when you forgive someone, you show them the face of God. Third, forgiveness is a choice you can make even when the relationship needs time to heal.", "Is there a brother, sister, friend or classmate you are still holding something against? You may be the one God wants to use to show them His face."],
        verse: simple("To see your face is like seeing the face of God, now that you have received me favourably.", "Genesis 33:10"),
        lessons: ["Repentance often involves humbly undoing the damage our pride has caused.", "When we forgive, we reflect the face of God to others.", "Forgiveness is a choice; rebuilding trust and closeness can take time."],
        questions: ["How does Jacob bowing to Esau reverse the blessing he stole?", "Why do you think Jacob said Esau’s welcome was like seeing the face of God?", "What is the difference between forgiving someone and fully trusting them again?"],
        listen: "Set a timer for two minutes. Ask God: ‘Who needs to see your face through my forgiveness?’ Write down the name that comes, and one step you could take.",
        prayer: ["Father, thank you for running to welcome me.", "I choose to forgive…, and I trust you with justice.", "Let people see your face through me."],
        mission: { compass: "love", text: "Take one concrete step towards reconciliation this week: an apology, a kind message or simply letting go of a grudge." },
        journal: "Write a letter you may never send to someone who hurt you, in which you choose to forgive. Then write a prayer for them." }),
      af: own({ title: "God se Gesig in ’n Broer", bibleStory: "Genesis 33, Lukas 15", readPassage: "Genesis 33:1–17 en Lukas 15:20",
        story: ["Ná twintig jaar, ’n nag van stoei en ’n nuwe naam ontmoet Jakob vir Esau. Die toneel is versigtig geskryf, en dit beloon stadige lees.", "Jakob gaan voor sy familie uit en ‘het sewe keer tot op die grond gebuig terwyl hy nader aan sy broer kom’. Dit is ’n doelbewuste omkering. Jare vroeër het Jakob ’n seën gesteel wat gesê het: ‘Mag jou moeder se seuns voor jou buig.’ Nou buig Jakob voor Esau. Bekering lyk dikwels daarna om, so ver as wat ons kan, die skade ongedaan te maak wat ons trots veroorsaak het.", "Toe: ‘Esau het Jakob tegemoet gehardloop en hom omhels; hy het sy arms om sy nek gegooi en hom gesoen. En hulle het gehuil.’ Lees Lukas 15:20, die vader wat die verlore seun verwelkom: ‘Hy het na sy seun toe gehardloop, sy arms om hom gegooi en hom gesoen.’ Die ooreenkoms is opvallend. In Jesus se storie verteenwoordig die figuur wat hardloop en omhels, God die Vader.", "Jakob sê dan iets wat ryk aan teologie is: ‘Om jou gesig te sien, is soos om die gesig van God te sien, noudat jy my so goed ontvang het.’ Hy het pas by die rivier God van aangesig tot aangesig gesien. Nou, in sy broer se onverdiende welkom, sien hy weer God se karakter. Genade wat deur mense gegee word, weerspieël die genade van God.", "Maar die storie is ook realisties. Die broers versoen, maar hulle trek nie saam in nie. Jakob weier beleefd om saam met Esau te reis en vestig hom elders. Vergifnis en versoening is werklik, maar om vertroue en nabyheid te herstel kan tyd neem, en soms bly gesonde grense oor. Dit is nie mislukking nie. Dit is wysheid.", "Wat beteken dit vir jou? Eerstens kan jy God se vergifnis net so vrylik ontvang as wat Jakob Esau se welkom ontvang het. Tweedens, as jy iemand vergewe, wys jy vir hulle die gesig van God. Derdens is vergifnis ’n keuse wat jy kan maak selfs as die verhouding tyd nodig het om te genees.", "Is daar ’n broer, suster, maat of klasmaat teen wie jy nog iets hou? Jy is dalk die een wat God wil gebruik om vir hulle sy gesig te wys."],
        verse: simple("Om jou gesig te sien, is soos om die gesig van God te sien, noudat jy my so goed ontvang het.", "Genesis 33:10"),
        lessons: ["Bekering sluit dikwels in om nederig die skade ongedaan te maak wat ons trots veroorsaak het.", "As ons vergewe, weerspieël ons die gesig van God vir ander.", "Vergifnis is ’n keuse; om vertroue en nabyheid weer op te bou kan tyd neem."],
        questions: ["Hoe draai Jakob se buig voor Esau die seën om wat hy gesteel het?", "Hoekom dink jy het Jakob gesê Esau se welkom was soos om die gesig van God te sien?", "Wat is die verskil tussen om iemand te vergewe en om hulle weer heeltemal te vertrou?"],
        listen: "Stel ’n tydhouer vir twee minute. Vra God: ‘Wie moet u gesig deur my vergifnis sien?’ Skryf die naam neer wat opkom, en een tree wat jy kan neem.",
        prayer: ["Vader, dankie dat U gehardloop het om my te verwelkom.", "Ek kies om… te vergewe, en ek vertrou U met geregtigheid.", "Laat mense u gesig deur my sien."],
        mission: { compass: "love", text: "Neem hierdie week een konkrete tree na versoening: ’n verskoning, ’n gawe boodskap of om net ’n wrok te laat gaan." },
        journal: "Skryf ’n brief wat jy dalk nooit stuur nie aan iemand wat jou seergemaak het, waarin jy kies om te vergewe. Skryf dan ’n gebed vir hulle." }),
    },
  },

  "j02-n07": {
    "8-9": {
      en: own({ title: "Campfire Night: Wells in the Desert",
        story: ["Welcome to the first campfire of the Trail of the Living Water! This week you followed a family through the desert: Hagar, who discovered the God who sees; a servant who prayed at a well; Isaac, the peacemaker; Jacob, who met God at a stairway to heaven and wrestled his way to a new name; and two brothers who ran into each other’s arms. Through all of it, God was faithful to a messy, imperfect family, and He is faithful to yours too."],
        game: "Name meanings: look up what your own name means, and the names of your family members. Then talk about the names God gives His children: loved, forgiven, chosen, child of God.",
        lessons: [],
        questions: ["Which person this week did you relate to most: Hagar, the servant, Isaac, Jacob or Esau?", "What did you learn about how God treats imperfect people?", "What have you sensed God saying in your Listening times?"],
        prayer: ["El Roi, thank you that you see me.", "Thank you for guiding me, making room for me and giving me a new name.", "Help me to forgive like Esau."],
        mission: { compass: "listen", text: "Learn Genesis 16:13 by heart this week and say it to someone in your family." },
        journal: "Draw a well. Around it, write the six treasures about God from this week, and circle the one you need most right now." }),
      af: own({ title: "Kampvuuraand: Putte in die Woestyn",
        story: ["Welkom by die eerste kampvuur van Die Pad van die Lewende Water! Hierdie week het jy ’n familie deur die woestyn gevolg: Hagar, wat die God ontdek het wat sien; ’n dienskneg wat by ’n put gebid het; Isak, die vredemaker; Jakob, wat God by ’n trap na die hemel ontmoet en tot ’n nuwe naam gestoei het; en twee broers wat in mekaar se arms gehardloop het. Deur dit alles was God getrou aan ’n deurmekaar, onvolmaakte familie, en Hy is ook getrou aan joune."],
        game: "Naambetekenisse: soek op wat jou eie naam beteken, en die name van jou familielede. Gesels dan oor die name wat God vir sy kinders gee: geliefd, vergewe, gekies, kind van God.",
        lessons: [],
        questions: ["Met watter persoon hierdie week het jy die meeste geïdentifiseer: Hagar, die dienskneg, Isak, Jakob of Esau?", "Wat het jy geleer oor hoe God onvolmaakte mense behandel?", "Wat het jy aangevoel God sê in jou Luistertye?"],
        prayer: ["El Roi, dankie dat U my sien.", "Dankie dat U my lei, vir my plek maak en my ’n nuwe naam gee.", "Help my om te vergewe soos Esau."],
        mission: { compass: "listen", text: "Leer hierdie week Genesis 16:13 uit jou kop en sê dit vir iemand in jou familie." },
        journal: "Teken ’n put. Skryf rondom dit die ses skatte oor God van hierdie week, en omkring die een wat jy nou die meeste nodig het." }),
    },
    "10-12": {
      en: own({ title: "Campfire Night: Wells in the Desert",
        story: ["This week you followed one family through four generations of messy, real life: a used and abandoned servant, a long journey guided by prayer, a powerful man choosing peace, a cheating runaway met by grace, a night-long wrestle that ended in a new name, and a brother who ran to forgive. Not one of these people was perfect. But God was faithful to every one of them. That is the God you are getting to know: El Roi, who sees; the God who guides, makes room, stays with us, renames us and makes peace."],
        game: "Trace the family tree from Abraham to Jacob’s sons, then mark where each of this week’s stories fits. Notice how God kept His promise through every generation.",
        lessons: [],
        questions: ["Which story this week challenged your thinking most? Why?", "What do these stories show about how God works through imperfect people?", "What have you been wrestling with or sensing in your Listening journal this week?"],
        prayer: ["God, thank you that you are faithful to imperfect people like me.", "This week I learned that you…", "Keep growing me and give me peace with…"],
        mission: { compass: "listen", text: "Memorise Genesis 16:13 and Genesis 28:15 this week." },
        journal: "Write a short reflection: ‘Where I see Jacob in myself, and how God is changing me.’",
        parentCheckIn: "Ask a parent: ‘Is there a time God was faithful to our family even when things were messy?’ Then share which story from this week stood out to you, and why." }),
      af: own({ title: "Kampvuuraand: Putte in die Woestyn",
        story: ["Hierdie week het jy een familie deur vier geslagte van deurmekaar, regte lewe gevolg: ’n gebruikte en verlate diensmeisie, ’n lang reis wat deur gebed gelei is, ’n magtige man wat vrede kies, ’n bedrieglike weghardloper wat deur genade ontmoet word, ’n nag lange stoeiery wat in ’n nuwe naam eindig, en ’n broer wat gehardloop het om te vergewe. Nie een van hierdie mense was volmaak nie. Maar God was getrou aan elkeen van hulle. Dit is die God wat jy leer ken: El Roi, wat sien; die God wat lei, plek maak, by ons bly, ons ’n nuwe naam gee en vrede maak."],
        game: "Volg die stamboom van Abraham tot by Jakob se seuns, en merk dan waar elkeen van hierdie week se stories inpas. Let op hoe God sy belofte deur elke geslag gehou het.",
        lessons: [],
        questions: ["Watter storie hierdie week het jou denke die meeste uitgedaag? Hoekom?", "Wat wys hierdie stories oor hoe God deur onvolmaakte mense werk?", "Waarmee het jy hierdie week gestoei, of wat het jy in jou Luisterjoernaal aangevoel?"],
        prayer: ["God, dankie dat U getrou is aan onvolmaakte mense soos ek.", "Hierdie week het ek geleer dat U…", "Laat my aanhou groei en gee my vrede met…"],
        mission: { compass: "listen", text: "Leer hierdie week Genesis 16:13 en Genesis 28:15 uit jou kop." },
        journal: "Skryf ’n kort nadenke: ‘Waar ek Jakob in myself sien, en hoe God my verander.’",
        parentCheckIn: "Vra ’n ouer: ‘Is daar ’n tyd toe God getrou was aan ons familie selfs al was dinge deurmekaar?’ Vertel dan watter storie van hierdie week vir jou uitgestaan het, en hoekom." }),
    },
  },
};
